const usePhaseFade = \(cues: CueTiming\[\], cueIdx: number\) => \{
  const frame = useCurrentFrame\(\);
  if \(cueIdx >= cues.length\) return 0;
  const cue = cues\[cueIdx\];
  const next = cueIdx \+ 1 < cues.length \? cues\[cueIdx \+ 1\] : undefined;
  const fadeIn = interpolate\(frame, \[cue.relativeStartFrame, cue.relativeStartFrame \+ 12\], \[0, 1\], clamp\);
  const fadeOut = next
    \? interpolate\(frame, \[next.relativeStartFrame - 8, next.relativeStartFrame\], \[1, 0\], clamp\)
    : 1;
  return fadeIn \* fadeOut;
\};

